INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64789870', 64789870, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN ANALIS MAKRO PEMBANGUNAN NASIONAL I', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 99998184, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '6', 'Posisi Jasa Konsultan Analis Makro Pembangunan Nasional memiliki Ruang Lingkup sebagai berikut: Melakukan analisis indikator makro pembangunan nasional, meliputi pertumbuhan ekonomi, inflasi, ketenagakerjaan, kemiskinan, ketimpangan, dan indikator makro relevan lainnya. Mengolah dan menganalisis data statistik makro dari sumber resmi (BPS, K/L terkait, dan sumber lain yang relevan). Menyusun catatan analisis perkembangan ekonomi dan pembangunan nasional secara berkala. Mendukung penyusunan bahan kebijakan dan narasi pembangunan makro untuk kebutuhan internal. Melakukan analisis isu makro strategis yang berdampak pada pencapaian sasaran pembangunan nasional. Membantu pemantauan kinerja pembangunan nasional berdasarkan indikator makro dan target yang ditetapkan. Menyusun ringkasan analitis dan bahan presentasi terkait isu pembangunan makro. Melakukan koordinasi teknis dengan tim terkait dalam rangka penyediaan bahan analisis. Menghimpun dan mengelola referensi data dan kajian makro pembangunan sebagai bahan pendukung analisis. Melaksanakan tugas analitis lainnya yang relevan dengan pembangunan makro nasional sesuai arahan pimpinan.', 'Memiliki pendidikan minimal Sarjana (S1) di bidang Ekonomi, Ekonomi Pembangunan, Ekonomi Publik, Perencanaan Pembangunan, Kebijakan Publik dengan konsentrasi ekonomi, atau bidang lain yang relevan dengan analisis ekonomi makro dan pembangunan nasional. Memiliki pengalaman kerja minimal 5 (lima) tahun di bidang analisis ekonomi makro, perencanaan pembangunan, perumusan kebijakan ekonomi, atau penyusunan kajian ekonomi pembangunan, khususnya di lingkungan pemerintahan, lembaga negara, atau institusi kebijakan publik. Bukan berstatus ASN aktif dan tidak sedang terikat kontrak permanen dengan pekerjaan lain; Tidak pernah diberhentikan dengan tidak terhormat sebagai Pegawai/ASN/Konsultan Individu; Diutamakan Warga Negara Indonesia (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk) Mempunyai status valid keterangan Wajib Pajak berdasarkan Hasil Konfirmasi Status Wajib Pajak (KSWP); Memiliki bukti potong pajak atas pengahasilan tertinggi pada institusi/Lembaga pekerjaan sebelumnya atau bukti lapor SPT pajak tahunan terakhir; Memiliki pengalaman langsung dalam melakukan analisis indikator ekonomi makro, antara lain pertumbuhan ekonomi, inflasi, ketenagakerjaan, kemiskinan, ketimpangan, dan indikator ekonomi makro pembangunan lainnya. Memiliki pemahaman yang mendalam mengenai sistem perencanaan pembangunan nasional, termasuk RPJPN, RPJMN, dan RKP, serta keterkaitannya dengan kerangka kebijakan ekonomi makro. Menguasai prinsip, metode, dan teknik analisis ekonomi makro dan pembangunan, termasuk analisis tren, evaluasi kinerja makro, dan penilaian implikasi kebijakan ekonomi. Mampu menyusun analisis ekonomi makro dan rekomendasi kebijakan yang komprehensif, argumentatif, dan dapat dipertanggungjawabkan secara metodologis dan substantif. Memiliki kemampuan untuk mengawal substansi kebijakan ekonomi makro strategis lintas sektor, termasuk identifikasi risiko dan dampaknya terhadap pencapaian sasaran pembangunan nasional. Memiliki pengalaman dalam koordinasi lintas kementerian dan/atau lembaga terkait isu ekonomi makro dan pembangunan nasional. Mampu menyusun dokumen strategis ekonomi makro dan pembangunan, antara lain policy brief, analytical note, ringkasan eksekutif, dan laporan analisis ekonomi tingkat senior. Memiliki kemampuan komunikasi strategis dalam menyampaikan hasil analisis ekonomi makro kepada pimpinan, tim teknis, dan pemangku kepentingan. Memiliki integritas, independensi profesional, dan etika kerja yang tinggi dalam pelaksanaan analisis dan pendampingan kebijakan ekonomi. Mampu menjaga kerahasiaan data, dokumen, dan informasi strategis negara yang diperoleh selama pelaksanaan tugas. Tidak sedang menjalani sanksi administratif atau proses hukum serta tidak memiliki konflik kepentingan yang dapat mempengaruhi independensi analisis maupun pelaksanaan tugas. Bekerja berdasarkan pendekatan berbasis keluaran (output based) serta memiliki komitmen untuk hadir secara fisik dan melakukan perjalanan dinas apabila dibutuhkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1730537);
