INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64789351', 64789351, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN JUNIOR PENGUATAN TATA KELOLA DAN IDENTIFIKASI TUGAS, PROSES BISNIS LINGKUP PERENCANAAN MAKRO PEMBANGUNAN', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 59236362, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '6', 'Posisi Jasa Konsultan Penguatan Tata Kelola Reformasi Birokrasi memiliki Ruang Lingkup sebagai berikut: Mendukung pelaksanaan agenda Reformasi Birokrasi sesuai kebijakan dan pedoman yang berlaku. Membantu penyusunan dan pemutakhiran bahan tata kelola, termasuk peta proses bisnis, alur kerja, dan mekanisme koordinasi internal. Menghimpun dan mengolah data pendukung terkait pelaksanaan reformasi birokrasi, akuntabilitas kinerja, dan tata kelola organisasi. Mendukung penyusunan bahan monitoring dan evaluasi pelaksanaan reformasi birokrasi. Membantu penyusunan laporan dan ringkasan kegiatan reformasi birokrasi. Melaksanakan koordinasi teknis dengan unit kerja terkait dalam rangka kelancaran pelaksanaan agenda reformasi birokrasi. Menyusun catatan dan dokumentasi non-arsip resmi sebagai bahan koordinasi internal. Melaksanakan tugas pendukung lainnya yang relevan dengan tata kelola dan reformasi birokrasi sesuai arahan pimpinan.', 'Memiliki pendidikan minimal Sarjana (S1) pada bidang Administrasi Publik/Negara, Manajemen, Kebijakan Publik, Hukum, Ekonomi, atau bidang lain yang relevan dengan tata kelola. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak. Memiliki pemahaman dasar mengenai konsep tata kelola organisasi, dan akuntabilitas kinerja. Mampu menghimpun, mengolah, dan menyusun data, informasi, serta bahan pendukung tata kelola. Mampu menyusun laporan, ringkasan, dan dokumentasi kegiatan dengan baik dan tepat waktu. Memiliki kemampuan dasar dalam monitoring dan evaluasi kegiatan organisasi. Mampu mengoperasikan aplikasi perkantoran (pengolah kata, lembar kerja, dan presentasi). Memiliki kemampuan komunikasi dan koordinasi yang baik dalam mendukung pelaksanaan Reformasi Birokrasi. Mampu bekerja secara mandiri maupun dalam tim serta mampu menindaklanjuti arahan pimpinan dengan baik. Memiliki kemampuan manajemen waktu, ketelitian, dan administrasi pekerjaan yang memadai. Memiliki integritas dan etika kerja yang baik serta mampu menjaga kerahasiaan data dan informasi. Tidak sedang menjalani sanksi administratif atau hukum dan tidak memiliki konflik kepentingan dalam pelaksanaan tugas.. Bukan berstatus ASN aktif dan tidak sedang terikat kontrak permanen dengan pekerjaan lain; Tidak pernah diberhentikan dengan tidak terhormat sebagai Pegawai/ASN/Konsultan Individu; Diutamakan Tenaga Ahli dalam negeri (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk) Mempunyai status valid keterangan Wajib Pajak berdasarkan Hasil Konfirmasi Status Wajib Pajak (KSWP); Memiliki bukti potong pajak atas pengahasilan tertinggi pada institusi/Lembaga pekerjaan sebelumnya atau bukti lapor SPT pajak tahunan terakhir; Bekerja berdasarkan output keluaran (Output Based), dan memiliki komitmen untuk hadir secara fisik apabila dibutuhkan dan melakukan perjalanan apabila dibutuhkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1732100);
