INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64791118', 64791118, 'analyze_legacy', 'Kementerian Komunikasi dan Digital', 'central', 'Sekretariat Jenderal Komdigi', 'Pemeliharaan FM 200', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 100000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, keg, @ 100000000 )', '1. Pemeliharaan FM 200 ( 1, keg, @ 100000000 );', '• Pemeriksaan Visual dan Fisik Komponen - Pemeriksaan tabung media pemadam (cek kondisifisik, label, dan segel). - Pemeriksaan nozzle dan pipa distribusi (tidak tersumbat, tidak berkarat/lepas). - Verifikasi bracket penyangga tabung dan jalur pipa. • Pemeriksaan Tekanan dan Indikator - Cek tekanan isi media pada gauge (harus sesuaispesifikasi pabrikan). - Validasi indikator tekanan sistem (tidak berada dizona merah). - Pemeriksaan switch tekanan (pressure switch) dankoneksi kabelnya. • Pemeriksaan Panel Kontrol dan Alarm - Tes fungsional panel kontrol kebakaran (Fire AlarmControl Panel). - Verifikasi status lampu indikator dan buzzer alarm. - Simulasi alarm (manual release dan alarm deteksiasap) • Pemeriksaan Sensor dan Detektor - Pengujian smoke detector dan heat detector di areadata center. - Cek sensitivitas dan respon waktu detektor terhadapsimulasi asap panas. - Kalibrasi ulang sensor sesuai siklus tahunan atauSOP vendor. • Sistem Pelepasan Media (Tanpa Discharge Nyata) - Pengujian simulasi aktivasi sistem (non-dischargetest mode). - Verifikasi logika aktivasi berlapis (2-zone detectionlogic). - Pemeriksaan sistem manual release dan delay timer. • Pemeriksaan Keamanan dan Akses - Cek rambu peringatan dan jalur evakuasi. - Pastikan valve manual dalam posisi normal (tidak tertutup kecuali perintah). - Tombol emergency dan interlock HVAC/shutdown server. • Dokumentasi dan Pelaporan - Pengisian checklist maintenance lengkap. - Pencatatan status setiap komponen. - Rekomendasi perbaikan atau penggantian jika ditemukan kelainan. - Penandatanganan Berita Acara Pemeliharaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1733527);
