INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64790649', 64790649, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Kajian Analisis Stabilitas Eksternal dalam Pengawalan Percepatan Pertumbuhan Ekonomi Nasional dan Daerah', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 48109092, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '4 OB', '1. Menyusun kajian strategis utamanya dalam stabilisasi eksternal Indonesia untuk mengawal percepatan pertumbuhan ekonomi di nasional dan daerah; 2. Mengumpulkan dan mengolah data terkait ekonomi dari layanan penyedia data, seperti BPS, BI, CEIC, World Bank, dan lainnya; 3. Menyusun model ekonomi serta proyeksi jangka pendek dan menengah-panjang; 4. Melakukan koordinasi dan diskusi dengan Kementerian, Lembaga, Pemerintah Daerah, Akademisi, dan/atau stakeholders terkait; 5. Melakukan tugas pembantuan terkait Pengawalan Percepatan Pertumbuhan Ekonomi Nasional dan Daerah; dan 6. Penugasan lain yang dikoordinasikan oleh Direktorat Perencanaan Ekonomi Makro dan Pengembangan Model Pembangunan.', '1. Bukan PNS atau anggota TNI/Polri; 2. Pendidikan minimal S1 di bidang Ilmu Ekonomi/Ekonomi Pembangunan dengan konsentrasi pada jurusan ekonomi Internasional dan yang terkait; 3. Memiliki pengalaman kerja minimal 3 tahun di bidang ekonomi; 4. IPK minimal 3,25 (dari skala 4,00); 5. Mahir dalam pengoperasian software statistik yang mencakup Microsoft Excel, Stata, Matlab, Python, dan lainnya; 6. Bersedia bekerja penuh waktu di Kantor Kementerian PPN/Bappenas Jakarta; 7. Memiliki kemampuan untuk bekerja secara mandiri maupun dalam tim; 8. Memiliki pengalaman menulis laporan, paparan, dan infografis; 9. Bersedia untuk tidak mendapatkan hal – hal sebagai berikut : a. Fasilitas Barang Milik Negara. b. THR dan Gaji 13. c. BPJS (Kesehatan dan Ketenagakerjaan). d. Fasilitas klinik kecuali dalam kondisi darurat. e. Menuntut diangkat menjadi ASN.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1733901);
