INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64791246', 64791246, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN PENYUSUNAN KAJIAN, BENCHMARK, DAN PENDAMPINGAN STRATEGIS TRANSFORMASI INDONESIA', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 74295272, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '8', 'Menghimpun dan menyiapkan data indikator makro pembangunan dari sumber resmi (BPS, K/L terkait, dan sumber relevan lainnya). Membantu pengolahan awal data statistik makro (tabulasi, grafik sederhana, ringkasan angka). Menyusun bahan pendukung analisis makro berdasarkan arahan Jasa Konsultan Analis. Membantu penyiapan catatan perkembangan indikator makro pembangunan secara berkala. Mendukung penyusunan ringkasan analitis sederhana terkait isu makro pembangunan. Menyiapkan bahan presentasi dan visualisasi data sederhana untuk kebutuhan internal. Menghimpun dan mengelola referensi data dan dokumen analisis makro sebagai bahan pendukung. Membantu pelaksanaan pemantauan indikator makro pembangunan. Melaksanakan koordinasi teknis internal untuk kelancaran penyusunan bahan analisis. Melaksanakan tugas pendukung lainnya yang relevan dengan analisis makro pembangunan sesuai arahan Jasa Konsultan.', 'Memiliki latar belakang pendidikan minimal Sarjana (S1) di bidang ekonomi, ekonomi pembangunan, statistik, perencanaan pembangunan, kebijakan publik, atau bidang lain yang relevan dengan analisis ekonomi makro. Memiliki pengalaman kerja di bidang pengolahan data, analisis ekonomi, perencanaan pembangunan, atau kegiatan analitis sejenis menjadi nilai tambah. Memiliki pemahaman dasar mengenai indikator ekonomi makro pembangunan, antara lain pertumbuhan ekonomi, inflasi, ketenagakerjaan, kemiskinan, dan ketimpangan. Mampu menghimpun, mengolah, dan menyajikan data statistik makro dalam bentuk tabulasi, grafik sederhana, dan ringkasan angka. Bukan berstatus ASN aktif dan tidak sedang terikat kontrak permanen dengan pekerjaan lain; Tidak pernah diberhentikan dengan tidak terhormat sebagai Pegawai/ASN/Konsultan Individu; Diutamakan Warga Negara Indonesia (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk) Mempunyai status valid keterangan Wajib Pajak berdasarkan Hasil Konfirmasi Status Wajib Pajak (KSWP); Memiliki bukti potong pajak atas pengahasilan tertinggi pada institusi/Lembaga pekerjaan sebelumnya atau bukti lapor SPT pajak tahun Mampu menghimpun, mengolah, dan menyajikan data statistik makro dalam bentuk tabulasi, grafik sederhana, dan ringkasan angka. Mampu menyiapkan bahan pendukung analisis makro berdasarkan arahan Jasa Konsultan Analis. Memiliki kemampuan dasar dalam penggunaan perangkat lunak pengolahan data dan presentasi untuk mendukung kegiatan analisis. Memiliki kemampuan komunikasi yang baik serta mampu bekerja secara cermat, sistematis, dan sesuai arahan. Mampu bekerja secara mandiri maupun dalam tim serta mendukung koordinasi teknis internal. Memiliki integritas, etika kerja, dan tanggung jawab yang tinggi dalam pelaksanaan tugas. Mampu menjaga kerahasiaan data, informasi, dan dokumen yang diperoleh selama pelaksanaan kegiatan. Tidak sedang menjalani sanksi administratif atau proses hukum serta tidak memiliki konflik kepentingan yang dapat mempengaruhi pelaksanaan tugas.an terakhir; Tidak sedang menjalani sanksi administratif atau proses hukum serta tidak memiliki konflik kepentingan yang dapat memengaruhi pelaksanaan tugas.Bekerja berdasarkan pendekatan berbasis keluaran (output based) serta memiliki komitmen untuk hadir secara fisik dan melakukan perjalanan dinas apabila dibutuhkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1735188);
