INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64732028', 64732028, 'analyze_legacy', 'Kab. Sleman', 'kabkota', 'SEKRETARIAT DAERAH', 'Bucket Souvenir-Penyediaan Kebutuhan Rumah Tangga Sekretariat Daerah', 'Barang', 'E-Purchasing', 'DI Yogyakarta, Sleman (Kab.)', 14450000, 'January 2026', 'APBD', 1, 1, '1 paket', 'Bucket Souvenir-Penyediaan Kebutuhan Rumah Tangga Sekretariat Daerah', 'Bucket Souvenir-Penyediaan Kebutuhan Rumah Tangga Sekretariat Daerah', 14450000, 'high', 'Pengadaan bucket souvenir pada sekretariat daerah tidak tampak sebagai kebutuhan operasional rumah tangga kantor yang esensial. Berdasarkan judul item, belanja ini berindikasi bersifat seremonial/non-prioritas sehingga seluruh nilai pengadaan layak dicermati sebagai potensi pemborosan anggaran.', NULL, NULL, 3, 1, 1, 1, 1, 1735903);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64790811', 64790811, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN PENGELOLA KOORDINASI STRATEGIS SEKRETARIAT TRANSFORMASI NASIONAL DAN DAERAH', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 65454546, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '6', 'Posisi Jasa Konsultan Pengelola Koordinasi Strategis Sekretariat Transformasi Nasional dan Daerah di Sekretariat Deputi Bidang Perencanaan Makro Pembangunan Tahun 2026 memiliki Ruang Lingkup sebagai berikut: Melaksanakan fungsi koordinator sekretariat melalui: Mengoordinasikan dan mengevaluasi pendampingan penyelesaian dokumen pendampingan Mengoordinasikan rapat/kunjungan lapangan/focus group discussion (FGD)/kegiatan koordinasi lain baik dengan pihak internal (lintas kedeputian/sektor) ataupun pihak eksternal dalam rangka melaksanakan pendampingan Membantu Sekretaris Deputi Bidang Perencanaan Makro Pembangunan dalam melakukan penyusunan manual book untuk Sekretariat Transformasi Nasional dan Daerah. Membantu Sekretaris Deputi Bidang Perencanaan Makro Pembangunan dalam melakukan pendampingan terhadap Sekretariat Transformasi Nasional dan Daerah, yang mencakup: Persiapan pembentukan Sekretariat Transformasi Daerah Pengendalian Perencanaan, seperti pendampingan penyusunan RKPD dan/atau penentuan proyek prioritas Pengendalian pelaksanaan, seperti pendampingan monev yang dilakukan Sekretariat Transformasi Daerah melalui dashboard maupun info-memo Membantu Sekretaris Deputi Bidang Perencanaan Makro Pembangunan dalam melakukan pendampingan dan/atau memberikan masukan atas RKP Tahun 2027 Membantu Sekretaris Deputi Bidang Perencanaan Makro Pembangunan dalam melakukan pendampingan terhadap penyusunan PP sebagai penjabaran misi dari UU 59/2024 Membantu Sekretaris Deputi Bidang Perencanaan Makro Pembangunan dalam melakukan pendampingan dan/atau pengawalan pertumbuhan ekonomi 8% Membantu Sekretaris Deputi Bidang Perencanaan Makro Pembangunan dalam melakukan koordinasi dengan mitra terkait, yaitu pemerintah pusat maupun daerah dalam rangka melakukan pendampingan Membantu Sekretaris Deputi Bidang Perencanaan Makro Pembangunan dalam melakukan tugas-tugas lainnya dalam rangka pencapaian Tujuan Sekretariat Transformasi Nasional dan Daerah', 'Pendidikan Jasa Konsultan Pendampingan Kegiatan Transformasi Indonesia minimal S1 bidang Ilmu Ekonomi atau Ekonomi Pembangunan, baik di dalam ataupun di luar negeri dan dapat dibuktikan dengan Ijazah atau dokumen resmi kelulusan atau sertifikat kelulusan; Memiliki pengalaman minimal 2 (Dua) tahun, baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak, dan dapat dibuktikan dengan surat kontrak dan atau surat pengalaman; Bukan berstatus ASN aktif dan tidak sedang terikat kontrak permanen dengan pekerjaan lain; Tidak pernah diberhentikan dengan tidak terhormat sebagai Pegawai/ASN/Konsultan Individu; Diutamakan Warga Negara Indonesia (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk) Mempunyai status valid keterangan Wajib Pajak berdasarkan Hasil Konfirmasi Status Wajib Pajak (KSWP); Memiliki bukti potong pajak atas pengahasilan tertinggi pada institusi/Lembaga pekerjaan sebelumnya atau bukti lapor SPT pajak tahunan terakhir; Bekerja berdasarkan output keluaran (Output Based), dan memiliki komitmen untuk hadir secara fisik apabila dibutuhkan dan melakukan perjalanan apabila dibutuhkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1735904);
