INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64792154', 64792154, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Junior Penyusunan Kajian Strategis sebagai Input Rencana Pengawalan Percepatan Pertumbuhan Ekonomi Nasional dan Daerah', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 38945456, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '4 OB', 'Ruang lingkup kegiatan ini adalah menyusun kajian analisis dalam mendukung Kegiatan Pengawalan Percepatan Pertumbuhan Ekonomi Nasional dan Daerah sejalan dengan agenda transformasi ekonomi makro jangka pendek dan menengah.', '1. Bukan PNS atau anggota TNI/Polri; 2. Pendidikan minimal S1 di bidang Ilmu Ekonomi/Ekonomi Pembangunan dengan konsentrasi pada jurusan ekonomi moneter dan yang terkait; 3. Memiliki pengalaman kerja minimal 2 tahun di bidang ekonomi; 4. IPK minimal 3,25 (dari skala 4,00); 5. Mahir dalam pengoperasian software statistik seperti R-Studio, Eviews, dan Stata; 6. Bersedia bekerja penuh waktu di Kantor Kementerian PPN/Bappenas Jakarta; 7. Memiliki kemampuan untuk bekerja secara mandiri maupun dalam tim; 8. Memiliki pengalaman menulis laporan dan infografis. 9. Jasa Asisten Konsultan bersedia untuk tidak mendapatkan hal-hal berikut: a. Fasilitas Barang Milik Negara; b. THR dan Gaji 13; c. BPJS (Kesehatan dan Ketenagakerjaan); d. Fasilitas Klinik kecuali dalam kondisi darurat; e. Menuntut diangkat menjadi ASN.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1736097);
