INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64791202', 64791202, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Dokumen Monitoring dan Pelaporan Implementasi COMCEC', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 48338444, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '4', 'Ruang lingkup secara detil dalam rangka Dukungan Substansi terhadap Sekretariat COMCEC Tahun 2026 adalah sebagai berikut: 1. Komunikasi dan koordinasi intensif dengan COMCEC Coordination Office (CCO) dalam rangka penjadwalan pertemuan dan agenda pembahasan terkait pelaksanaan peran Kementerian PPN/Bappenas selaku National Focal Point Indonesia untuk COMCEC. 2. Komunikasi dan koordinasi intensif dengan focal point Indonesia pada masing-masing working group COMCEC terkait pelaporan hasil-hasil pertemuan dan agenda pembahasan pada pertemuan tahunan masing-masing working group. 3. Komunikasi dan koordinasi intensif dengan lembaga-lembaga di bawah Organization of Islamic Countries (OIC) terkait pemberian bantuan kerja sama ekonomi dan teknis bagi pihak-pihak terkait di Indonesia. 4. Koordinasi dan kompilasi laporan implementasi Ministerial Policy Recommendation COMCEC yang telah dilakukan oleh Indonesia pada masing-masing working group, untuk dilaporkan setiap tahunnya ke dalam platform pelaporan COMCEC. 5. Identifikasi isu dan permasalahan yang berkembang serta kendala yang dihadapi terkait pembahasan pada masing-masing working group. 6. Pemantauan dan pelaporan update proses pengajuan tahunan COMCEC Project Funding oleh K/L melalui working group terkait melalui platform pengajuan proposal COMCEC. 7. Pelaporan tahunan dan update pelaksanaan tugas Kementerian PPN/Bappenas selaku national focal point Indonesia untuk COMCEC. 8. Administrasi kepartisipasian Kementerian PPN/Bappenas selaku National Focal Point Indonesia untuk COMCEC pada pertemuan: • Annual Follow-up Committee Meeting of the COMCEC • COMCEC Session and Ministerial Meeting', '1. Memiliki NPWP dan telah memenuhi kewajiban pajak tahunan; 2. Latar belakang pendidikan minimal Strata-1 (S1) di bidang Hubungan Internasional; 3. Memiliki pengalaman kerja minimal 1-3 tahun di bidang analisis kebijakan dan riset terkait hubungan internasional atau kerja sama antarnegara; 4. Bersedia dan mampu menyelesaikan pekerjaan dalam kurun waktu 9 (sembilan) bulan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1736544);
