INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64752457', 64752457, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Kantor Pertanahan KAB ACEH TENGGARA', 'Sewa Kendaraan Operasional Tahun 2026 Kantor Pertanahan Kabupaten Aceh Tenggara', 'Barang', 'E-Purchasing', 'Aceh, Aceh Tenggara (Kab.)', 132000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 0, '12 Bulan @11.000.000', 'Kebutuhan sewa kendaraan operasional roda 4 (empat) Double Gardan yang difungsikan sebagai transportasi operasional dalam rangka mendukung pelaksanaan kegiatan kedinasan sebagai pengganti pengadaan kendaraan melalui pembelian.', 'Performa kendaraan dirancang untuk mendukung kegiatan operasional pada berbagai kondisi medan, termasuk jalan tidak beraspal dan area dengan tingkat kesulitan akses tinggi. Kendaraan menggunakan bahan bakar diesel dengan kapasitas mesin berkisar 2.400–2.500 cc, menghasilkan tenaga dan torsi yang memadai untuk menunjang mobilitas, daya tahan, serta efisiensi penggunaan dalam kegiatan lapangan. Sistem penggerak double gardan (4x4) memastikan stabilitas, traksi, dan keandalan kendaraan dalam mendukung pelaksanaan tugas kedinasan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1738947);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64790222', 64790222, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Sekretariat Focal Point Indonesia Untuk ASEAN Coordinating Task-Force on Blue Economy (ACTF-BE) Tahun 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 41830692, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '4', '1. Melakukan koordinasi terkait penyusunan ASEAN Blue Economy Implementation Plan 2. Identifikasi isu dan permasalahan yang berkembang serta kendala yang dihadapi terkait penyusunan ASEAN Blue Economy Implementation Plan dan ASEAN Blue Economy Implementation Roadmap. 3. Melakukan koordinasi teknis terkait penyampaian proposal Indonesia pada RCEP Implementation Support Program (RISP). 4. Memberikan dukungan teknis untuk persiapan the 3rd ACTF-BE Meeting dan the 4th ASEAN Blue Economy Forum di tahun 2026. 5. Memberikan dukungan teknis untuk koordinasi persiapan dan pelaksanaan the 3rd ACTF-BE Meeting dan the 4th ASEAN Blue Economy Forum di tahun 2026 di lingkup Kementerian PPN/Bappenas, baik dengan Kementerian/Lembaga terkait maupun di internal Kementerian PPN/Bappenas. 6. Melakukan koordinasi terkait penyusunan posisi Indonesia pada the 3rd ACTF-BE Meeting, the 4th ASEAN Blue Economy Forum, dan the 5th Committee on Sustainable Growth RCEP Meeting di tahun 2026. 7. Administrasi kepartisipasian Kedeputian Bidang Perencanaan Makro Pembangunan Kementerian PPN/Bappenas selaku focal point ACTF-BE Indonesia dan Shepherd ACTF-BE 2026-2027.', '1. Memiliki NPWP dan telah memenuhi kewajiban pajak tahunan; 2. Memiliki latar belakang pendidikan minimal Strata-1 (S1) di bidang Hubungan Internasional; 3. Memiliki pengalaman kerja minimal 3 tahun di bidang analisis kebijakan dan riset terkait hubungan internasional, organisasi internasional, atau kerja sama antarnegara; 4. Bersedia dan mampu menyelesaikan pekerjaan dalam kurun waktu 10 (sepuluh) bulan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1738948);
