INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64792023', 64792023, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Kajian Hilirisasi Sektor Kelautan dan Perikanan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 44022632, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '4', 'Ruang lingkup pekerjaan secara rinci dalam rangka Studi Pemetaan Ekosistem Kebijakan Pengembangan Hilirisasi Sektor Kelautan Perikanan Tahun 2026, meliputi: 1. Melakukan pengumpulan dan analisis isu strategis, tantangan utama, serta dinamika kebijakan dan pasar yang mempengaruhi pengembangan hilirisasi sektor kelautan dan perikanan. 2. Menyusun kerangka konseptual pengembangan hilirisasi sektor kelautan dan perikanan sebagai dasar analisis kebijakan dan perumusan arah pengembangan. 3. Melakukan pemetaan pemangku kepentingan dan identifikasi permasalahan utama pada setiap tahapan rantai nilai hilirisasi sektor kelautan dan perikanan. 4. Mengompilasi informasi benchmark dan praktik terbaik pengembangan hilirisasi sektor kelautan dan perikanan di negara pembanding yang relevan bagi Indonesia. 5. Melakukan analisis kesenjangan antara benchmark dan praktik terbaik internasional dengan kondisi eksisting hilirisasi sektor kelautan dan perikanan di Indonesia. 6. Mengidentifikasi dan menganalisis hambatan kebijakan dan regulasi yang berpotensi menghambat pengembangan hilirisasi sektor kelautan dan perikanan. 7. Melakukan seleksi komoditas unggulan hilirisasi sektor kelautan dan perikanan berdasarkan kesiapan industri dan potensi pasar. 8. Menyusun opsi akselerasi pengembangan hilirisasi sektor kelautan dan perikanan berdasarkan temuan awal hasil analisis. 9. Menyusun strategi pelibatan pemangku kepentingan untuk mendukung percepatan pengembangan hilirisasi sektor kelautan dan perikanan.', '1. Memiliki NPWP dan telah memenuhi kewajiban pajak tahunan; 2. Memiliki latar belakang pendidikan minimal S1 di bidang Ilmu Ekonomi; 3. Memiliki pengalaman dalam kajian terkait perencanaan tahunan organisasi atau rencana jangka menengah di lingkungan pemerintah pusat minimal dalam 2 (dua) tahun terakhir; 4. Memiliki pemahaman dan pengalaman analitis dalam pengembangan dan pemanfaatan Indonesia Blue Economy Index, mencakup analisis nilai tambah sektor kelautan dan perikanan, keterkaitan antarsektor dan antarwilayah, serta dimensi ekonomi, sosial, dan lingkungan dalam mendukung perencanaan pembangunan ekonomi biru. 5. Memiliki kompetensi dalam analisis economic dan product complexity (ECI–PCI) sebagai dasar perumusan kebijakan pengembangan industri, diversifikasi ekspor, dan peningkatan daya saing wilayah. 6. Memiliki pengalaman dalam pekerjaan di bidang ekonomi dengan lingkup permasalahan skala nasional dalam kurun waktu minimal 2 (dua) tahun terakhir; dan; 7. Memiliki pengalaman dalam pekerjaan di bidang hilirisasi dalam konteks perencanaan pembangunan nasional.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1739514);
