INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64792153', 64792153, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN MANAJEMEN PIMPINAN', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 87970912, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '8', 'Posisi Jasa Konsultan Manajemen Pimpinan memiliki Ruang Lingkup sebagai berikut: Mendukung pengelolaan agenda kegiatan pimpinan, termasuk rapat, pertemuan, dan kegiatan kedinasan lainnya. Membantu penyiapan bahan pendukung pimpinan, seperti ringkasan materi, catatan rapat, dan poin-poin pembahasan. Melakukan koordinasi operasional dengan unit kerja terkait dalam rangka pelaksanaan agenda pimpinan. Mendukung tindak lanjut arahan pimpinan, termasuk pemantauan penyampaian informasi dan respons unit kerja terkait. Menyusun catatan dan ringkasan hasil rapat/pertemuan sebagai bahan koordinasi internal. Membantu pengelolaan komunikasi non-formal dan non-administratif pimpinan dengan pihak internal dan eksternal. Menghimpun dan mengelola bahan informasi pendukung untuk kebutuhan pimpinan. Melaksanakan tugas pendukung manajemen pimpinan lainnya sesuai arahan, sepanjang tidak mencakup kewenangan administratif ASN.', 'Memiliki pendidikan minimal Sarjana (S1) pada bidang Administrasi Publik/Negara, Manajemen, Sekretari, Ilmu Sosial, Komunikasi, atau bidang lain yang relevan dengan manajemen dan dukungan pimpinan. Memiliki pengalaman kerja minimal 2 (dua) tahun dalam bidang dukungan manajemen pimpinan, administrasi eksekutif, sekretariat, atau koordinasi kegiatan organisasi.. Bukan berstatus ASN aktif dan tidak sedang terikat kontrak permanen dengan pekerjaan lain; Tidak pernah diberhentikan dengan tidak terhormat sebagai Pegawai/ASN/Konsultan Individu; Diutamakan Warga Negara Indonesia (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk) Mempunyai status valid keterangan Wajib Pajak berdasarkan Hasil Konfirmasi Status Wajib Pajak (KSWP); Memiliki bukti potong pajak atas pengahasilan tertinggi pada institusi/Lembaga pekerjaan sebelumnya atau bukti lapor SPT pajak tahunan terakhir; Memahami tata kelola organisasi pemerintahan serta etika kerja di lingkungan instansi pemerintah. Mampu melakukan pengelolaan agenda pimpinan, termasuk penjadwalan, koordinasi kegiatan, dan pengaturan pertemuan. Mampu menyiapkan bahan rapat, bahan pertemuan, dan bahan pendukung pimpinan secara rapi dan sistematis. Mampu menyusun notulensi, catatan hasil pertemuan, dan ringkasan arahan pimpinan dengan baik dan jelas. Memiliki kemampuan komunikasi dan koordinasi yang baik dalam mendukung hubungan kerja pimpinan dengan unit internal maupun pihak eksternal. Mampu melakukan pemantauan dan penyiapan bahan tindak lanjut arahan pimpinan sesuai kebutuhan. Mampu bekerja secara mandiri maupun dalam tim, serta memiliki kemampuan manajemen waktu yang baik. Menguasai aplikasi perkantoran (pengolah kata, lembar kerja, presentasi, dan surat elektronik) untuk mendukung tugas manajemen pimpinan. Memiliki integritas, etika kerja, dan sikap profesional dalam mendukung pelaksanaan tugas pimpinan. Mampu menjaga kerahasiaan informasi dan dokumen kedinasan yang diperoleh selama pelaksanaan tugas. Tidak sedang menjalani sanksi administratif atau hukum dan tidak memiliki konflik kepentingan yang dapat mempengaruhi pelaksanaan tugas.Bekerja berdasarkan output keluaran (Output Based), dan memiliki komitmen untuk hadir secara fisik apabila dibutuhkan dan melakukan perjalanan apabila dibutuhkan.', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 1739600);
